#!/usr/bin/env python3
from __future__ import annotations

import json
from pathlib import Path
from typing import Any


TASK_ID = "CSX-200_Q2"
PACKAGE_ID = "CSX-200"

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_003_Locked_event_anchor_2023_Greece_wildfires.json",
    "data/physical_hazard/physical_hazard_009_Sentinel-2_SR_Harmonized_dNBR.json",
    "data/remote_sensing/remote_sensing_004_Google_Satellite_Embedding_annual_cosine-change_stats.json",
]

THRESHOLDS = {
    "dnbr_high_severity_min": 0.66,
    "dnbr_broad_positive_mean_min": 0.27,
    "mixed_scene_mean_max": 0.0,
    "mixed_scene_std_min": 0.10,
    "annual_local_change_max_min": 0.75,
    "annual_scene_mean_max": 0.10,
    "annual_peak_mean_ratio_min": 10.0,
}


def package_dir() -> Path:
    workspace_root = Path(__file__).resolve().parents[3]
    return workspace_root / "event_packages" / "standard_event_packages" / "packages" / PACKAGE_ID


def read_json(package: Path, rel_path: str) -> Any:
    return json.loads((package / rel_path).read_text(encoding="utf-8"))


def round_metric(value: float) -> float:
    return round(float(value), 6)


def safe_ratio(numerator: float, denominator: float) -> float:
    if denominator == 0:
        raise ValueError("Cannot divide by zero in surface-change ratio")
    return numerator / denominator


def compute_metrics() -> dict[str, Any]:
    package = package_dir()
    event = read_json(package, "metadata/event.json")
    anchor = read_json(
        package,
        "data/event_reports/event_reports_003_Locked_event_anchor_2023_Greece_wildfires.json",
    )
    dnbr_product = read_json(
        package,
        "data/physical_hazard/physical_hazard_009_Sentinel-2_SR_Harmonized_dNBR.json",
    )
    annual_product = read_json(
        package,
        "data/remote_sensing/remote_sensing_004_Google_Satellite_Embedding_annual_cosine-change_stats.json",
    )

    dnbr_stats = dnbr_product["stats"]
    annual_stats = annual_product["stats"]

    dnbr_max = float(dnbr_stats["sentinel2_dnbr_max"])
    dnbr_mean = float(dnbr_stats["sentinel2_dnbr_mean"])
    dnbr_min = float(dnbr_stats["sentinel2_dnbr_min"])
    dnbr_std = float(dnbr_stats["sentinel2_dnbr_stdDev"])
    annual_max = float(annual_stats["alphaearth_1_minus_cosine_max"])
    annual_mean = float(annual_stats["alphaearth_1_minus_cosine_mean"])
    annual_min = float(annual_stats["alphaearth_1_minus_cosine_min"])
    annual_std = float(annual_stats["alphaearth_1_minus_cosine_stdDev"])

    dnbr_peak_abs_mean_ratio = safe_ratio(dnbr_max, abs(dnbr_mean))
    dnbr_peak_z = safe_ratio(dnbr_max - dnbr_mean, dnbr_std)
    annual_peak_mean_ratio = safe_ratio(annual_max, annual_mean)
    annual_peak_z = safe_ratio(annual_max - annual_mean, annual_std)

    flags = {
        "local_high_dnbr": dnbr_max >= THRESHOLDS["dnbr_high_severity_min"],
        "uniform_scene_burn": dnbr_mean >= THRESHOLDS["dnbr_broad_positive_mean_min"],
        "mixed_scene": (
            dnbr_mean < THRESHOLDS["mixed_scene_mean_max"]
            and dnbr_std >= THRESHOLDS["mixed_scene_std_min"]
        ),
        "localized_annual_change": (
            annual_max >= THRESHOLDS["annual_local_change_max_min"]
            and annual_mean < THRESHOLDS["annual_scene_mean_max"]
            and annual_peak_mean_ratio >= THRESHOLDS["annual_peak_mean_ratio_min"]
        ),
    }

    if (
        flags["local_high_dnbr"]
        and flags["mixed_scene"]
        and flags["localized_annual_change"]
        and not flags["uniform_scene_burn"]
    ):
        answer = "consistent_patchy_high_severity_fire_change"
    elif flags["uniform_scene_burn"]:
        answer = "broad_positive_burn_signal"
    elif not flags["local_high_dnbr"]:
        answer = "weak_high_severity_surface_change"
    else:
        answer = "mixed_surface_change_without_full_consistency"

    metrics = {
        "dnbr": {
            "max": round_metric(dnbr_max),
            "mean": round_metric(dnbr_mean),
            "min": round_metric(dnbr_min),
            "std_dev": round_metric(dnbr_std),
            "peak_abs_mean_ratio": round_metric(dnbr_peak_abs_mean_ratio),
            "peak_z": round_metric(dnbr_peak_z),
            "pre_window": dnbr_product["windows"]["pre"],
            "post_window": dnbr_product["windows"]["post"],
            "counts": dnbr_product["counts"],
        },
        "annual_change": {
            "max": round_metric(annual_max),
            "mean": round_metric(annual_mean),
            "min": round_metric(annual_min),
            "std_dev": round_metric(annual_std),
            "peak_mean_ratio": round_metric(annual_peak_mean_ratio),
            "peak_z": round_metric(annual_peak_z),
            "pre_year": annual_product["pre_year"],
            "post_year": annual_product["post_year"],
        },
        "flags": flags,
        "answer": answer,
        "event": {
            "package_id": PACKAGE_ID,
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_window": (
                f"{anchor['temporal_window']['start_date']} to "
                f"{anchor['temporal_window']['end_date']}"
            ),
        },
    }
    return metrics


