def build_output() -> dict[str, Any]:
    metrics = compute_metrics()
    dnbr = metrics["dnbr"]
    annual = metrics["annual_change"]
    flags = metrics["flags"]

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": PACKAGE_ID,
        "task_type": "numeric",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "target_family": "numeric_diagnosis",
        "primary_gt": {
            "dnbr_metrics": {
                "dnbr_max": dnbr["max"],
                "dnbr_mean": dnbr["mean"],
                "dnbr_std_dev": dnbr["std_dev"],
                "dnbr_peak_z": dnbr["peak_z"],
            },
            "annual_change_metrics": {
                "annual_change_max": annual["max"],
                "annual_change_mean": annual["mean"],
                "annual_peak_mean_ratio": annual["peak_mean_ratio"],
            },
            "threshold_flags": flags,
            "consistency_class": metrics["answer"],
            "interpretation": "Local high-severity dNBR is consistent with patchy fire-linked surface change, not uniform burn.",
        },
        "answer_schema": {
            "required_top_level_fields": [
                "dnbr_metrics",
                "annual_change_metrics",
                "threshold_flags",
                "consistency_class",
                "interpretation",
            ],
            "required_numeric_fields": [
                "dnbr_max",
                "dnbr_mean",
                "dnbr_std_dev",
                "dnbr_peak_z",
                "annual_change_max",
                "annual_change_mean",
                "annual_peak_mean_ratio",
            ],
        },
        "event": metrics["event"],
        "thresholds": THRESHOLDS,
        "key_values": {
            "dnbr": dnbr,
            "annual_change": annual,
            "threshold_flags": flags,
            "consistency_class": metrics["answer"],
            "tolerances": {
                "absolute_numeric": 0.005,
                "ratio_or_z_score": 0.05,
            },
        },
        "decision_rule": {
            "formulae": {
                "dnbr_peak_z": "(dnbr_max - dnbr_mean) / dnbr_std_dev",
                "annual_peak_mean_ratio": "annual_change_max / annual_change_mean",
            },
            "classification_logic": (
                "The patchy high-severity class is assigned when local_high_dnbr, mixed_scene, "
                "and localized_annual_change are true while uniform_scene_burn is false."
            ),
            "rejected_states": [
                "broad uniform burn: fails because dNBR mean is below 0.27 and is negative",
                "weak surface change: fails because dNBR max exceeds 0.66",
                "broad annual transformation: fails because annual mean is below 0.10 despite a high local maximum",
            ],
        },
        "judge_anchors": {
            "canonical_stance": (
                "The local post-fire metrics support patchy high-severity fire-linked surface change "
                "inside a mixed scene, not uniform severe burn or a smoke-only reading."
            ),
            "must_include": [
                "dNBR max meets the high-severity threshold",
                "dNBR mean is negative, so the scene-average signal is not broad positive burn",
                "dNBR spread and z-score show a localized high-end signal",
                "annual change is concentrated because max/mean is about 13.17 while mean is about 0.061",
            ],
            "forbidden_overclaims": [
                "treating the whole scene as uniformly severe burn",
                "using the negative mean to erase the local high-dNBR fire signal",
                "claiming observed population losses or management conclusions from these metrics",
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
        "rubric": rubric(),
    }


def main() -> None:
    output = build_output()
    Path(__file__).with_name("computed_gt.json").write_text(
        json.dumps(output, indent=2, sort_keys=False) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
